mcqs.append(q("mcq-crim-01-009", "ch-crim-01", "top-crim-01-01", "Under Section 1(5)(c) BNS / S. 4(3) IPC, Indian courts have extraterritorial jurisdiction over any person targeting a:", ["Foreign government portal", "Computer resource located in India", "Commercial ship registered in Panama", "Foreign satellite in space"], 1, "B", "Section 1(5)(c) covers cyber-attacks targeting computer resources located in India.", {"A": "Foreign assets not covered.", "B": "Correct; computer resource located in India.", "C": "Panamanian flag state.", "D": "Treaty law."}, "Medium", "BNS Section 1(5)(c)", "Understand cyber jurisdiction."))
