mcqs.append(q("mcq-crim-01-011", "ch-crim-01", "top-crim-01-02", "The fundamental maxim 'Actus non facit reum nisi mens sit rea' literally translates to:", ["An act makes a man guilty only if civilly actionable", "An act does not make a person guilty unless the mind is also guilty", "A guilty mind alone without an act is punishable", "Every illegal omission automatically constitutes actus reus"], 1, "B", "Crime requires concurrence of guilty act and guilty mind.", {"A": "Civil law irrelevant.", "B": "Correct; act plus guilty mind required.", "C": "Bare intention not punishable.", "D": "Omission must be illegal and accompanied by mens rea."}, "Easy", "General Principles of Criminal Law", "Master foundational criminal maxim."))
