mcqs.append(q("mcq-crim-01-015", "ch-crim-01", "top-crim-01-02", "Which offence under the penal code is an example of strict liability where honest belief regarding age is no defence?", ["Kidnapping from lawful guardianship", "Culpable Homicide", "Extortion", "Defamation"], 0, "A", "In R v. Prince and Section 137 BNS / Section 361 IPC, kidnapping from lawful guardianship is strict liability regarding age.", {"A": "Correct; kidnapping is strict liability regarding age.", "B": "Requires intent/knowledge.", "C": "Requires intentional fear.", "D": "Requires intent/knowledge."}, "Medium", "BNS Section 137 / R v. Prince", "Recognize strict liability exceptions."))
mcqs.append(q("mcq-crim-01-016", "ch-crim-01", "top-crim-01-02", "What is the proximity test formulated in Abhayanand Mishra v. State of Bihar (1961) to distinguish attempt from preparation?", ["Accused does an act towards commission after completing preparation", "Accused does the last possible act", "Accused confesses verbally", "Factual impossibility test"], 0, "A", "Attempt commences when an act towards commission is done after completing preparation.", {"A": "Correct; active step towards execution constitutes attempt.", "B": "Last act doctrine rejected.", "C": "No confession required.", "D": "Impossibility does not negate attempt."}, "Hard", "AIR 1961 SC 1698", "Distinguish attempt from preparation."))
mcqs.append(q("mcq-crim-01-017", "ch-crim-01", "top-crim-01-02", "A puts his hand in B's pocket intending to steal money, but finds the pocket completely empty. A is guilty of:", ["No offence due to impossibility", "Attempt to commit theft under Section 62 BNS / S. 511 IPC", "Mischief", "Criminal trespass"], 1, "B", "Factual impossibility does not bar attempt liability; picking an empty pocket is attempt to commit theft.", {"A": "Impossibility is no defence.", "B": "Correct; attempt to commit theft.", "C": "No damage done.", "D": "Not trespass."}, "Easy", "BNS Section 62 / IPC S. 511 Illus. (b)", "Understand attempt with factual impossibility."))
mcqs.append(q("mcq-crim-01-018", "ch-crim-01", "top-crim-01-02", "Which mental element in criminal law signifies the highest degree of blameworthiness?", ["Negligence", "Rashness", "Knowledge", "Intention"], 3, "D", "Hierarchy: Intention > Knowledge > Rashness > Negligence.", {"A": "Lowest culpability.", "B": "Reckless indifference.", "C": "Awareness of probability.", "D": "Correct; Intention is highest culpability."}, "Medium", "Mens Rea Hierarchy", "Master degrees of mental culpability."))
mcqs.append(q("mcq-crim-01-019", "ch-crim-01", "top-crim-01-02", "A purchases matchsticks and petrol to burn down B's house. While walking towards B's house, A is intercepted 2 km away. A has committed:", ["Attempt to commit mischief by fire", "Only preparation, which is not punishable", "Criminal conspiracy", "Completed mischief"], 1, "B", "Purchasing materials and walking is still preparation; no direct proximate step taken at the house.", {"A": "No direct ignition step.", "B": "Correct; merely preparation.", "C": "Acted alone.", "D": "No damage occurred."}, "Medium", "Malkiat Singh, (1969) 1 SCC 157", "Apply proximity test to preparation versus attempt."))
mcqs.append(q("mcq-crim-01-020", "ch-crim-01", "top-crim-01-02", "Under Section 62 BNS / Section 511 IPC, what is the default punishment for attempt when no express provision exists?", ["One-fourth of longest term of imprisonment", "One-half of the longest term of imprisonment provided for the offence, or fine, or both", "Full term of imprisonment", "Fine of Rs 1,000 only"], 1, "B", "Default penalty for attempt is up to one-half of the longest term provided for the offence.", {"A": "Default fine limit.", "B": "Correct; one-half of maximum term.", "C": "Completed offence penalty.", "D": "Not fine only."}, "Easy", "BNS Section 62", "Recall general penalty formula for attempt."))

